// ===== CATEGORY / SEARCH MAP - edit freely =====
// label   = EXACT category text the Daily Feed pages filter on (must match the
//           site category pills: Coins, Sports Cards, Trading Cards, etc.)
// queries = search terms; each term = one YouTube search.list call = 100 units.
// 12 categories x 3 queries = 36 calls/run = 3,600 quota units/run, x2/day = 7,200.
const CATEGORIES = [
  { label: "Coins",         queries: ["rare coins", "coin collecting", "silver stacking"] },
  { label: "Sports Cards",  queries: ["sports card collecting", "card breaks", "sports cards investing"] },
  { label: "Trading Cards", queries: ["pokemon cards opening", "magic the gathering cards", "tcg collecting"] },
  { label: "Comics",        queries: ["comic book collecting", "comic book haul", "key comics investing"] },
  { label: "Sneakers",      queries: ["sneaker collection", "sneaker unboxing", "rare sneakers"] },
  { label: "Watches",       queries: ["watch collecting", "luxury watch review", "vintage watches"] },
  { label: "Jewelry",       queries: ["estate jewelry", "vintage jewelry", "fine jewelry collecting"] },
  { label: "Stamps",        queries: ["stamp collecting", "philately", "rare stamps"] },
  { label: "Toys",          queries: ["vintage toys collecting", "action figure collection", "toy hunting"] },
  { label: "Vintage",       queries: ["vintage collectibles", "antique haul", "vintage thrift finds"] },
  // NOTE: no "Hollywood" pill on the site -> mapped to "Memorabilia". Change if you prefer.
  { label: "Memorabilia",   queries: ["movie memorabilia", "hollywood memorabilia", "film prop collecting"] },
  { label: "Memorabilia",   queries: ["sports memorabilia", "autograph collecting", "game used memorabilia"] }
];

return [{ json: { config: C, categories: CATEGORIES } }];

// Flatten categories x queries into one item per search call.
// Build query string manually (n8n Code sandbox has no URLSearchParams).
const cfg = $("Config").first().json.config;
const cats = $("Config").first().json.categories;
const publishedAfter = new Date(Date.now() - (cfg.lookback_hours || 36) * 3600000).toISOString();
const enc = encodeURIComponent;
const out = [];
for (const c of cats) {
  for (const q of c.queries) {
    const qs = [
      "part=snippet",
      "type=video",
      "order=date",
      "maxResults=" + enc(String(cfg.max_results_per_query || 10)),
      "q=" + enc(q),
      "publishedAfter=" + enc(publishedAfter),
      "relevanceLanguage=en",
      "key=" + enc(cfg.youtube_api_key)
    ].join("&");
    out.push({ json: {
      category: c.label, query: q,
      url: "https://www.googleapis.com/youtube/v3/search?" + qs
    }});
  }
}
return out;

