const ctxs = $("Build Search Requests").all();
const results = $input.all();
const seen = new Set();
const videos = [];
for (let i = 0; i < results.length; i++) {
  const ctx = (ctxs[i] && ctxs[i].json) || {};
  const body = results[i] && results[i].json;
  const items = (body && body.items) || [];
  for (const it of items) {
    const vid = it && it.id && it.id.videoId;
    if (!vid || seen.has(vid)) continue;
    seen.add(vid);
    const sn = it.snippet || {};
    const url = "https://www.youtube.com/watch?v=" + vid;
    const thumbs = sn.thumbnails || {};
    const thumb = (thumbs.high || thumbs.medium || thumbs.default || {}).url || null;
    videos.push({ json: {
      category: ctx.category, query: ctx.query, video_id: vid,
      title: (sn.title || "").trim(),
      description: (sn.description || "").slice(0, 1200),
      channel_title: sn.channelTitle || "",
      published_at: sn.publishedAt || null,
      image_url: thumb, url: url,
      url_hash: md5(url)
    }});
  }
}
return videos;

// Drop videos whose url_hash already exists in cf_content_items (last 90 days).
// Mirrors the News Agent: on any lookup failure, pass everything through.
const cfg = $("Config").first().json.config;
const items = $input.all();
if (items.length === 0) return [];
const since = new Date(Date.now() - 90 * 86400000).toISOString();
let known = new Set();
try {
  let offset = 0;
  const pageSize = 1000;
  while (true) {
    const res = await this.helpers.httpRequest({
      method: "GET",
      url: cfg.supabase_url + "/rest/v1/cf_content_items"
         + "?type=eq.video&created_at=gte." + since + "&select=url_hash",
      headers: {
        apikey: cfg.supabase_key,
        Authorization: "Bearer " + cfg.supabase_key,
        Range: offset + "-" + (offset + pageSize - 1)
      },
      json: true
    });
    if (!Array.isArray(res) || res.length === 0) break;
    for (const r of res) { if (r.url_hash) known.add(r.url_hash); }
    if (res.length < pageSize) break;
    offset += pageSize;
  }
} catch (e) { return items; }
return items.filter(it => !known.has(it.json.url_hash));

const cfg = $("Config").first().json.config;
const v = $json;
const prompt = [
"You are the content scorer for a collectibles network's Daily Feed.",
"Score this YouTube video and return ONLY a JSON object (no prose) with keys:",
'- summary: one plain sentence, max 30 words. Plain words, no hype, no AI-slop',
'  words (delve, supercharge, elevate, game-changer, robust, seamless, dive into).',
'- quality_score: integer 1-10. How worthwhile this video is on a collectibles',
'  feed for the given category. 10 = genuinely useful/interesting to collectors',
'  (real finds, market talk, education, news). Low = spam, reseller ads, clickbait,',
'  off-topic, get-rich hype, or low-effort filler.',
'- is_relevant: boolean. True if it fits the category and the collectibles hobby.',
"",
"VIDEO:",
"category: " + v.category,
"channel: " + v.channel_title,
"title: " + v.title,
"description: " + v.description
].join("\n");
return { json: { ...v, haiku_body: {
  model: cfg.haiku_model, max_tokens: 400,
  messages: [{ role: "user", content: prompt }]
}}};

// Parse Haiku output, set status, build the exact cf_content_items payload.
// Per the News Agent fix: never silently drop low/irrelevant items - save them
// as 'pending'. Only quality_score >= approve_min_score auto-approves to the feed.
const cfg = $("Config").first().json.config;
const ctxs = $("Build Haiku Request").all();
const results = $input.all();
const runId = "yt-" + new Date().toISOString().slice(0, 16);
const out = [];
for (let i = 0; i < results.length; i++) {
  const v = ctxs[i].json;
  let parsed = null;
  try {
    const txt = results[i].json.content[0].text;
    parsed = JSON.parse(txt.match(/\{[\s\S]*\}/)[0]);
  } catch (e) {
    parsed = { summary: (v.title || "").slice(0, 160), quality_score: 1, is_relevant: false };
  }
  const qs = Math.max(1, Math.min(10, Number(parsed.quality_score) || 1));
  const relevant = parsed.is_relevant !== false;
  const status = (relevant && qs >= (cfg.approve_min_score || 5)) ? "approved" : "pending";
  out.push({ json: {
    type: "video", category: v.category, title: v.title,
    summary: parsed.summary || "", url: v.url, image_url: v.image_url,
    source_name: v.channel_title, source_platform: "youtube", author: v.channel_title,
    video_duration_seconds: null, is_journalistic: false,
    published_at: v.published_at, status: status, quality_score: qs,
    agent_run_id: runId, agent_model: cfg.haiku_model, agent_confidence: qs / 10,
    url_hash: v.url_hash,
    raw_payload: { video_id: v.video_id, query: v.query, channel: v.channel_title }
  }});
}
return out;
